# Import of required libraries
import skyramp
import os
import time

from SkyrampUtils import (
    create_household,
    create_recipe,
    delete_recipe,
    get_recipe,
    get_recipe_global,
    get_user_self,
)


# URL for test requests
URL_localhost = skyramp.get_base_url("SKYRAMP_TEST_BASE_URL", "http://localhost:9000")


def test_integration():
    # Invocation of Skyramp Client
    client = skyramp.Client()
    # Definition of authentication header
    headers = {}
    if os.getenv("SKYRAMP_TEST_TOKEN") is not None:
        headers["Authorization"] = "Bearer " + os.getenv("SKYRAMP_TEST_TOKEN")

    # Declaration of variables
    recipes = "household-scope-probe"

    self_GET_response = get_user_self(client, headers)

    assert len(skyramp.get_response_value(self_GET_response, "id")) == 36
    assert len(skyramp.get_response_value(self_GET_response, "groupId")) == 36
    assert len(skyramp.get_response_value(self_GET_response, "householdId")) == 36
    assert "@" in skyramp.get_response_value(self_GET_response, "email")

    households_POST_response = create_household(
        client,
        headers,
        skyramp.unique_suffix("hh-scope-probe"),
        skyramp.get_response_value(self_GET_response, "groupId"),
    )

    assert skyramp.get_response_value(households_POST_response, "name").startswith("hh-scope-probe")
    assert skyramp.get_response_value(households_POST_response, "groupId") == skyramp.get_response_value(self_GET_response, "groupId")
    assert len(skyramp.get_response_value(households_POST_response, "id")) == 36

    recipes_POST_response = create_recipe(client, headers, "Household Scope Probe")

    recipes_recipes_GET_response = get_recipe(client, headers, recipes)

    assert skyramp.get_response_value(recipes_recipes_GET_response, "slug") == recipes
    assert skyramp.get_response_value(recipes_recipes_GET_response, "name") == "Household Scope Probe"
    assert len(skyramp.get_response_value(recipes_recipes_GET_response, "id")) == 36
    assert skyramp.get_response_value(recipes_recipes_GET_response, "groupId") == skyramp.get_response_value(self_GET_response, "groupId")
    assert skyramp.get_response_value(recipes_recipes_GET_response, "householdId") == skyramp.get_response_value(self_GET_response, "householdId")

    global_GET_response = get_recipe_global(
        client,
        headers,
        skyramp.get_response_value(recipes_recipes_GET_response, "id"),
        expected_status=200,
    )

    assert skyramp.get_response_value(global_GET_response, "id") == skyramp.get_response_value(recipes_recipes_GET_response, "id")
    assert skyramp.get_response_value(global_GET_response, "slug") == skyramp.get_response_value(recipes_recipes_GET_response, "slug")
    assert skyramp.get_response_value(global_GET_response, "name") == skyramp.get_response_value(recipes_recipes_GET_response, "name")
    assert skyramp.get_response_value(global_GET_response, "groupId") == skyramp.get_response_value(recipes_recipes_GET_response, "groupId")
    assert skyramp.get_response_value(global_GET_response, "householdId") == skyramp.get_response_value(recipes_recipes_GET_response, "householdId")

    recipes_recipes_DELETE_response = delete_recipe(
        client,
        headers,
        skyramp.get_response_value(recipes_recipes_GET_response, "slug"),
    )

    assert skyramp.get_response_value(recipes_recipes_DELETE_response, "id") == skyramp.get_response_value(recipes_recipes_GET_response, "id")
    assert skyramp.get_response_value(recipes_recipes_DELETE_response, "slug") == recipes


if __name__ == "__main__":
    test_integration()
